class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def build_list(values):
    head = None
    tail = None
    for v in values:
        node = ListNode(v)
        if head is None:
            head = node
            tail = node
        else:
            tail.next = node
            tail = node
    return head

def list_to_array(head):
    result = []
    current = head
    while current is not None:
        if len(result) == 10000:
            raise ValueError("The returned list never reaches None (it loops back on itself).")
        result.append(current.val)
        current = current.next
    return result

def run_remove_nth(values, n):
    return list_to_array(remove_nth_from_end(build_list(values), n))

